// Parity check of Wan2.1's prompt layer (src/wan/text/ and the shared layer src/text/t5-tokenizer.ts)
// against the Python reference (ADR 0119 step 10a — decisions 1, 2 and 4). Needs neither a GPU nor
// real assets.
//
// The fixture `wan-text/parity.json` is generated by the recipe
// `tools/export-recipes/wan/umt5_tokenizer.py`. It holds
//  - the expectation per case (4 fixed + boundaries + random). When accepted, the output of upstream's
//    prompt_clean and the id sequence; when rejected, the reason. **The reference id sequence comes from
//    AutoTokenizer of transformers 5.14.1**, and accepted cases also carry the id sequence of the
//    tokenizer.json path (the two paths were checked to agree at generation time — here too the result
//    is compared with both)
//  - the **subset** of the vocabulary needed to reproduce them (the substrings of every case's fragments
//    — the lattice comes out the same as with the full vocabulary)
//  - the **whole** preprocessing table (promptClean)
//
// One behaviour is pinned: "the same string yields the same id sequence as upstream, or is rejected
// for the same reason".

import { readTextFile } from "@karume/test-support/fs";
import { test } from "vite-plus/test";
import { assert, assertEquals, assertInstanceOf, assertThrows } from "@std/assert";
import { ModelInputError } from "../src/errors.ts";
import { parseCodeRanges } from "../src/text/code-ranges.ts";
import { type T5Tables, T5UnigramTokenizer, type T5VocabEntry } from "../src/text/t5-tokenizer.ts";
import { parsePromptCleanTables, PromptCleanError } from "../src/wan/text/prompt-clean.ts";
import {
  parseWanTokenizerAsset,
  WAN_PROMPT_MIN_TOKENS,
  WAN_TOKENIZER_FORMAT,
  WanPromptEncoder,
} from "../src/wan/text/tokenizer.ts";
import { mirrorPresent, mirrorRoot, readMirrorAsset } from "./helpers/mirror.ts";

type FixtureCase = {
  readonly id: string;
  readonly why: string;
  readonly text: string;
  readonly cleaned?: string;
  readonly ids?: number[];
  readonly tokenizerJsonIds?: number[];
  readonly reject?: string;
};

type Fixture = {
  readonly maxLength: number;
  readonly minTokens: number;
  readonly t5: {
    readonly addedTokens: [string, number][];
    readonly unkId: number;
    readonly eosId: number;
    readonly minScore: number;
    readonly maxTokenLength: number;
    readonly space: unknown;
    readonly vocab: [string, number, number][];
  };
  readonly promptClean: unknown;
  readonly cases: FixtureCase[];
};

const fixture = JSON.parse(
  await readTextFile(new URL("./fixtures/wan-text/parity.json", import.meta.url)),
) as Fixture;

const t5Tables: T5Tables = {
  vocab: new Map<string, T5VocabEntry>(
    fixture.t5.vocab.map(([token, id, score]) => [token, { id, score }]),
  ),
  // MUST: not derived from the subset — the unknown-node score and the search width come from the
  // **full** vocabulary.
  minScore: fixture.t5.minScore,
  maxTokenLength: fixture.t5.maxTokenLength,
  unkId: fixture.t5.unkId,
  eosId: fixture.t5.eosId,
  addedTokens: new Map(fixture.t5.addedTokens),
  space: parseCodeRanges(fixture.t5.space, "space"),
  maxLength: fixture.maxLength,
};
const promptClean = parsePromptCleanTables(fixture.promptClean, "promptClean");
const encoder = new WanPromptEncoder({ t5: t5Tables, promptClean });

/** Tokenizer-side rejection reason → message marker (preprocessing rejections use `PromptCleanError.reason`). */
const TOKENIZER_REJECTS: Record<string, string> = {
  oov: "not in the vocabulary",
  "too-long": "upper bound 512",
  "too-short": `minimum ${WAN_PROMPT_MIN_TOKENS}`,
  "added-token": "special token",
  metaspace: "U+2581",
};
const PROMPT_CLEAN_REJECTS = new Set(["unassigned", "c1", "entity", "mojibake"]);

/**
 * The real asset (full vocabulary — when present, the check also runs independently of the subset
 * lattice): the `umt5_tokenizer` the published Wan2.2 distribution ships (ADR 0139 decision 1; the
 * same bytes as Wan2.1's).
 */
const WAN_MIRROR = mirrorRoot("karume-wan2.2");
const mirrorAsset = mirrorPresent(WAN_MIRROR)
  ? new TextDecoder().decode(await readMirrorAsset(WAN_MIRROR, "umt5_tokenizer"))
  : undefined;
if (mirrorAsset === undefined) {
  console.warn(
    `[karume] the mirror ${WAN_MIRROR.pathname} is absent (or not karume/5, or a sibling it references is ` +
      "absent), so the Wan full-vocabulary check is SKIPPED (fetch the karume-wan2.2 and karume-umt5-xxl " +
      "distributions into models/)",
  );
}

const caseById = (id: string): FixtureCase => {
  const found = fixture.cases.find((entry) => entry.id === id);
  if (found === undefined) throw new Error(`the fixture has no case ${id}`);
  return found;
};

// ---- The fixture itself -----------------------------------------------------

test("the fixture is not empty (a mix-up does not let every case pass through)", () => {
  // Kept first. If a misread or a failed generation leaves cases empty, the loops below run zero times
  // and a "green but checking nothing" state passes silently.
  assert(fixture.cases.length >= 200, `case count ${fixture.cases.length} is too small`);
  assertEquals(fixture.maxLength, 512);
  assertEquals(fixture.minTokens, WAN_PROMPT_MIN_TOKENS);
  assertEquals(fixture.t5.addedTokens.length, 304, "umT5 has 304 added tokens");
  const reasons = new Set(fixture.cases.map((entry) => entry.reject ?? "accepted"));
  for (const reason of ["accepted", ...PROMPT_CLEAN_REJECTS, ...Object.keys(TOKENIZER_REJECTS)]) {
    assert(reasons.has(reason), `no case with outcome ${reason}`);
  }
});

for (const testCase of fixture.cases) {
  test(`parity [${testCase.id}] ${testCase.why}`, () => {
    if (testCase.cleaned !== undefined) {
      assertEquals(encoder.clean(testCase.text), testCase.cleaned, "preprocessing output");
    }
    if (testCase.ids !== undefined) {
      const ids = encoder.encode(testCase.text);
      assertInstanceOf(ids, Int32Array);
      assertEquals([...ids], testCase.ids, "id sequence of transformers 5.14.1");
      assertEquals([...ids], testCase.tokenizerJsonIds, "id sequence of the tokenizer.json path");
      return;
    }
    const reason = testCase.reject as string;
    const error = assertThrows(() => encoder.encode(testCase.text), ModelInputError);
    if (PROMPT_CLEAN_REJECTS.has(reason)) {
      assertInstanceOf(error, PromptCleanError);
      assertEquals(error.reason, reason);
    } else {
      assert(!(error instanceof PromptCleanError), `failed in preprocessing: ${error.message}`);
      assert(
        error.message.includes(TOKENIZER_REJECTS[reason]),
        `no marker for reason ${reason}: ${error.message}`,
      );
    }
  });
}

// ---- Fixed prompts and boundaries (what the fixture cases actually exercise) ----------

test("the 4 fixed prompts are accepted with lengths 28 / 118 / 50 / 126, with the same id sequence on both paths", () => {
  const lengths = ["boxing-cats", "ferret", "cat-dog-baking", "negative"].map((name) => {
    const fixed = caseById(`fixed-${name}`);
    assertEquals(fixed.ids, fixed.tokenizerJsonIds);
    return encoder.encode(fixed.text).length;
  });
  assertEquals(lengths, [28, 118, 50, 126]);
});

test("the full-width comma `，` of the official negative becomes `,` (fix_character_width)", () => {
  const negative = caseById("fixed-negative");
  assert(negative.text.includes("，"));
  const cleaned = encoder.clean(negative.text);
  assert(!cleaned.includes("，") && cleaned.includes(","), cleaned);
});

test("upper bound: exactly 512 tokens is accepted, 513 is rejected (no silent truncation)", () => {
  const max = encoder.encode(caseById("max-512").text);
  assertEquals(max.length, 512);
  assertEquals(max.at(-1), fixture.t5.eosId, "ends with </s>");
  assertThrows(() => encoder.encode(caseById("over-513").text), ModelInputError, "upper bound 512");
});

test("lower bound: 2 tokens is accepted, the empty string and whitespace only (only </s>) are rejected", () => {
  assertEquals(encoder.encode("cat").length, WAN_PROMPT_MIN_TOKENS);
  for (const text of ["", " \n\t　 "]) {
    assertThrows(() => encoder.encode(text), ModelInputError, `minimum ${WAN_PROMPT_MIN_TOKENS}`);
  }
});

test("the rejection message carries the positive / negative label", () => {
  assertThrows(() => encoder.encode("𠀋", "negativePrompt"), ModelInputError, "negativePrompt");
  assertThrows(() => encoder.encode("cafÃ©", "negativePrompt"), PromptCleanError, "negativePrompt");
});

test("a lone surrogate is rejected as an input error before preprocessing", () => {
  assertThrows(() => encoder.encode("a\ud800b"), ModelInputError, "surrogate");
});

// ---- Policies of the shared layer (the rules themselves on a small synthetic vocabulary) ----

/** A T5 table with only the vocabulary `▁` / `a` / `b` (unk = 2, and the added token `<s>` is also id 2 — the same overlap as umT5). */
const tinyTables = (maxLength: number): T5Tables => ({
  vocab: new Map<string, T5VocabEntry>([
    ["▁", { id: 3, score: -1 }],
    ["a", { id: 4, score: -1 }],
    ["b", { id: 5, score: -1 }],
  ]),
  minScore: -1,
  maxTokenLength: 1,
  unkId: 2,
  eosId: 1,
  addedTokens: new Map([
    ["</s>", 1],
    ["<s>", 2],
  ]),
  space: [[0x20, 0x20]],
  maxLength,
});

test("out of vocabulary: the unk policy fuses into one unk, the reject policy throws ModelInputError", () => {
  const unk = new T5UnigramTokenizer(tinyTables(512), { unknown: "unk", overflow: "truncate" });
  assertEquals(unk.encode("axyb"), [3, 4, 2, 5, 1], "▁ a <unk> b </s>");
  const reject = new T5UnigramTokenizer(tinyTables(512), { unknown: "reject", overflow: "reject" });
  assertThrows(() => reject.encode("axyb", "check"), ModelInputError, '"xy"');
});

test("out-of-vocabulary is decided by the lattice's unknown node, not by id (an added token with the same id as unk_id passes)", () => {
  // umT5's unk_id 2 is also the id of `<s>`. Deciding out-of-vocabulary by whether the id sequence
  // contains 2 would reject `<s>` (an added token) in the text too, or conversely miss an unknown.
  const reject = new T5UnigramTokenizer(tinyTables(512), { unknown: "reject", overflow: "reject" });
  assertEquals(reject.encode("a<s>b"), [3, 4, 2, 3, 5, 1]);
});

test("upper bound: the reject policy accepts exactly maxLength including `</s>`, and throws one past it", () => {
  const reject = new T5UnigramTokenizer(tinyTables(5), { unknown: "reject", overflow: "reject" });
  // `▁a` is the 2 ids ▁ + a. "a a" = 4 ids + </s> = 5 (exactly the limit).
  assertEquals(reject.encode("a a"), [3, 4, 3, 4, 1]);
  assertThrows(() => reject.encode("a a b"), ModelInputError, "upper bound 5");
  // A form whose last fragment straddles the budget (4 + 2 = 6 ids) is rejected too.
  assertThrows(() => reject.encode("a aa"), ModelInputError, "upper bound 5");
  // An added token yields 1 id, so it is rejected when it comes right after an exactly full budget.
  assertThrows(() => reject.encode("a a</s>"), ModelInputError, "upper bound 5");
});

test("upper bound: a whitespace-only chunk right after an exactly full budget adds no ids, so it is not rejected", () => {
  // `a a` (4 ids) + `</s>` (1 id) fill the budget 5 exactly. The trailing " " is a chunk that is not an
  // added token but yields no fragment — rejecting before the chunk would reject an input that should
  // be accepted.
  const reject = new T5UnigramTokenizer(tinyTables(6), { unknown: "reject", overflow: "reject" });
  assertEquals(reject.encode("a a</s> "), [3, 4, 3, 4, 1, 1]);
});

test("upper bound: the truncate policy cuts leaving room for `</s>` (as anima's upstream does)", () => {
  const truncate = new T5UnigramTokenizer(tinyTables(5), { unknown: "unk", overflow: "truncate" });
  assertEquals(truncate.encode("a a b b"), [3, 4, 3, 4, 1]);
});

// ---- Reading the asset (external boundary) -----------------------------------

/** The smallest asset JSON (6 vocabulary rows + the fixture's preprocessing table). */
const minimalAsset = (patch: Record<string, unknown> = {}): Record<string, unknown> => ({
  format: WAN_TOKENIZER_FORMAT,
  maxLength: 512,
  unkId: 2,
  eosId: 1,
  addedTokens: [
    ["<pad>", 0],
    ["</s>", 1],
    ["<s>", 2],
    ["<unk>", 3],
  ],
  space: [[0x20, 0x20]],
  vocabText: "<pad>\n</s>\n<s>\n<unk>\n▁cat\n▁",
  scores: [0, 0, 0, 0, -1, -2],
  promptClean: fixture.promptClean,
  ...patch,
});

test("parseWanTokenizerAsset: an encoder built from the asset JSON can encode", () => {
  const assets = parseWanTokenizerAsset(minimalAsset());
  const tiny = new WanPromptEncoder(assets);
  assertEquals(tiny.maxLength, 512);
  assertEquals([...tiny.encode("cat cat")], [4, 4, 1]);
  assertThrows(() => tiny.encode("dog"), ModelInputError, "not in the vocabulary");
});

test("parseWanTokenizerAsset: an unknown format version is not read", () => {
  assertThrows(
    () => parseWanTokenizerAsset(minimalAsset({ format: "karume-wan-umt5-tokenizer/2" })),
    Error,
    "cannot read format",
  );
});

test("parseWanTokenizerAsset: a broken preprocessing table fails (it is not silently classified differently)", () => {
  const clean = fixture.promptClean as Record<string, unknown>;
  const broken = (patch: Record<string, unknown>): Record<string, unknown> =>
    minimalAsset({ promptClean: { ...clean, ...patch } });
  assertThrows(() => parseWanTokenizerAsset(broken({ badness: "[" })), Error, "regular expression");
  assertThrows(
    () =>
      parseWanTokenizerAsset(
        broken({
          assigned: [
            [10, 20],
            [15, 30],
          ],
        }),
      ),
    Error,
    "overlaps",
  );
  assertThrows(
    () =>
      parseWanTokenizerAsset(
        broken({
          width: [
            [0xff21, "A"],
            [0xff21, "B"],
          ],
        }),
      ),
    Error,
    "duplicate",
  );
  assertThrows(
    () => parseWanTokenizerAsset(broken({ ligatures: [[0xfb01, "\ud800"]] })),
    Error,
    "surrogate",
  );
  assertThrows(() => parseWanTokenizerAsset(broken({ width: [[-1, "A"]] })), Error, "code point");
});

test("parseWanTokenizerAsset: a badness expression that differs from the fixed translation of ftfy 6.3.1 fails without being executed", () => {
  // The asset is untrusted external input (it can point at any repo). Accepting an expression that is
  // merely syntactically valid would let an expression like `(a+)+$` grow backtracking exponentially in
  // preprocessing (including the check of the default negative at construction) and stall the event
  // loop. The translation is fixed (ADR 0119 decision 2), so an expression differing by even one
  // character is not accepted.
  const clean = fixture.promptClean as Record<string, unknown>;
  const source = clean.badness;
  assert(typeof source === "string");
  const withBadness = (badness: string): Record<string, unknown> =>
    minimalAsset({ promptClean: { ...clean, badness } });
  for (const [label, badness] of [
    ["expression with its last character changed", `${source.slice(0, -1)}X`],
    ["expression with catastrophic backtracking", "(a+)+$"],
  ]) {
    assertThrows(
      () => parseWanTokenizerAsset(withBadness(badness)),
      Error,
      "differs from the fixed translation of ftfy 6.3.1's BADNESS_RE",
      label,
    );
  }
  // Control: the fixture (the translation the recipe baked, as is) passes.
  parseWanTokenizerAsset(withBadness(source));
});

test("parseWanTokenizerAsset: the vocabulary value-range checks are the same as the shared T5 layer (duplicate rows, non-finite scores)", () => {
  assertThrows(
    () =>
      parseWanTokenizerAsset(
        minimalAsset({
          vocabText: "<pad>\n</s>\n<s>\n<unk>\n▁cat\n▁cat",
          scores: [0, 0, 0, 0, -1, -2],
        }),
      ),
    Error,
    "a duplicate is a corrupt distribution",
  );
  assertThrows(
    () => parseWanTokenizerAsset(minimalAsset({ scores: [0, 0, 0, 0, -1, Number.NaN] })),
    Error,
    "finite",
  );
});

test("parseWanTokenizerAsset: an added token must be a vocabulary row (below the row count, and the row of the same spelling)", () => {
  assertThrows(
    () => parseWanTokenizerAsset(minimalAsset({ addedTokens: [["<x>", 6]] })),
    Error,
    'tokenizer.addedTokens: "<x>" has id 6, which is >= the vocabulary row count 6',
  );
  assertThrows(
    () => parseWanTokenizerAsset(minimalAsset({ addedTokens: [["<unk>", 2]] })),
    Error,
    'tokenizer.addedTokens: "<unk>" has id 2, which disagrees with vocabulary row 3',
  );
});

// ---- Comparison on the real asset (full vocabulary) ---------------------------

test.skipIf(mirrorAsset === undefined)(
  "real asset: an encoder built from the full-vocabulary asset reaches the same outcome on every fixture case",
  () => {
    // The fixture's vocabulary is a subset (the substrings of the fragments), so this checks that reading
    // the asset (256K rows) and the full-vocabulary lattice also give the same id sequences / rejections.
    const full = new WanPromptEncoder(parseWanTokenizerAsset(JSON.parse(mirrorAsset as string)));
    for (const testCase of fixture.cases) {
      if (testCase.ids !== undefined) {
        assertEquals([...full.encode(testCase.text)], testCase.ids, testCase.id);
      } else {
        assertThrows(() => full.encode(testCase.text), ModelInputError, undefined, testCase.id);
      }
    }
  },
);
